// Sample REQUEST transformer script.
// Modified from version originally generated by Claude.
// For learning purposes only.

(function(inputs) {
    /* inputs structure: {
        prompt_data: object,
        request_data: object
    } */
    var requestData = inputs.request_data;
    var promptData = inputs.prompt_data;
    var prompt = promptData.prompt;
    var model = promptData.model;

    // Output the inputs object to the system log for inspection
    // gs.info('LLM Transformer inputs: ' + JSON.stringify(inputs));

    // DeepSeek's /chat/completions endpoint uses the OpenAI-compatible request shape:
    // { model, messages: [{role, content}], max_tokens, temperature, stream }
    var body = {
        model: model,
        messages: [{
            "role": "user",
            "content": prompt
        }],
        max_tokens: parseInt(promptData.max_tokens),
        temperature: parseFloat(promptData.temperature),
        stream: false
    };

    var headers = {};

    return {
        body: body,
        headers: headers
    };
})(inputs);

// Sample REQUEST transformer script.
// Modified from version originally generated by Claude.
// For learning purposes only.

(function(inputs) {
    /* write code here to transform the llm response into an array of text responses, using the inputs object
    inputs structure: {
        prompt_data: object,
        request_data: object,
        response_body: string,
        response_headers: string
    } */
    var requestData = inputs.request_data;
    var promptData = inputs.prompt_data;
    var responseBody = JSON.parse(inputs.response_body);
    // gs.info("DeepSeek response: " + inputs.response_body);
    var responseTexts = [];

    // A successful DeepSeek call returns an OpenAI-style chat.completion object:
    // { id, object, created, model, choices: [{ index, message: { role, content }, finish_reason }], usage }
    if (responseBody.choices && responseBody.choices.length > 0) {
        responseTexts.push(responseBody.choices[0].message.content);
    } else if (responseBody.error) {
        // DeepSeek error responses look like { "error": { "message": "...", "type": "...", "code": "..." } }
        gs.error("DeepSeek API error: " + JSON.stringify(responseBody.error));
    }

    return responseTexts;
})(inputs);